(() => {document.getElementById('simm-export').onclick=()=>{const state=SIMM_APP.getState(),l=SIMM_LESSONS.find(x=>x.id===state.lesson),r=l.compute(state.values),rows=[['SIMM educational calculation',l.name],['Reference','ISDA methodology 2.8+2512'],['Scope',l.scope],['Formula',l.formula],['Parameters','Teaching assumptions unless explicitly marked prescribed'],[],['Input','Value'],...l.inputs.map(d=>[d.label,state.values[d.id],d.unit||'']),[],r.headers,...r.rows,[],['Interpretation',r.explanation],...l.sources.map(x=>['Reference',...x])],csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='quantsense-simm-'+l.id+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};})();
